{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parseDocument, ParseError } from './parser.js'
import { toJson, toKeys } from './output.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
let root
try {
  root = parseDocument(input)
} catch (e) {
  if (e instanceof ParseError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(mode === 'json' ? toJson(root) : toKeys(root))
"}

{"file_path":"src/output.js","content":"import { Table, AotArray } from './parser.js'

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function children(node) {
  if (node instanceof Table) return sortedKeys(node).map((k) => [k, node.map.get(k)])
  return null
}

function ser(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  let items = null
  let open = '['
  let close = ']'
  if (node instanceof Table) {
    open = '{'
    close = '}'
    items = sortedKeys(node).map((k) => `${pad}${JSON.stringify(k)}: ${ser(node.map.get(k), indent + 1)}`)
  } else if (node instanceof AotArray || Array.isArray(node)) {
    const list = node instanceof AotArray ? node.items : node
    items = list.map((v) => pad + ser(v, indent + 1))
  } else {
    return JSON.stringify(node.value)
  }
  if (items.length === 0) return open + close
  return `${open}\n${items.join(',\n')}\n${end}${close}`
}

export function toJson(root) {
  return ser(root, 0) + '\n'
}

function typeOf(node) {
  if (node instanceof Table) return 'table'
  if (node instanceof AotArray || Array.isArray(node)) return 'array'
  return node.type
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node instanceof Table) {
      for (const [k, v] of children(node)) visit(v, path === null ? k : `${path}.${k}`)
    } else {
      const list = node instanceof AotArray ? node.items : node
      list.forEach((v, i) => visit(v, `${path}[${i}]`))
    }
  }
  const visit = (node, path) => {
    lines.push(`${path} ${typeOf(node)}`)
    if (node instanceof Table || node instanceof AotArray || Array.isArray(node)) walk(node, path)
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

export class Table {
  constructor() {
    this.map = new Map()
    this.header = false
  }
}

export class AotArray {
  constructor() {
    this.items = []
  }
}

class Fail extends Error {}
const fail = (m) => {
  throw new Fail(m)
}

const isWs = (c) => c === ' ' || c === '\t'
const BARE = /^[A-Za-z0-9_-]$/

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (this.i < this.s.length && isWs(this.s[this.i])) this.i++
  }
  /** True at end of line or at the start of a comment. */
  atEnd() {
    return this.i >= this.s.length || this.c === '#' || this.c === ';'
  }

  quoted() {
    const q = this.c
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const ch = this.c
      if (ch === q) {
        this.i++
        return out
      }
      if (q === '"' && ch === '\\') {
        this.i++
        if (this.i >= this.s.length) fail('unterminated string')
        const e = this.c
        const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          out += simple[e]
          this.i++
        } else if (e === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 5
        } else {
          const cp = String.fromCodePoint(this.s.codePointAt(this.i))
          fail(`invalid escape \\${cp}`)
        }
      } else {
        out += ch
        this.i++
      }
    }
  }

  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.c)) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = []
    this.ws()
    names.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }

  value(prefix) {
    const c = this.c
    if (this.i >= this.s.length || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
      fail('expected a value')
    }
    if (c === '"' || c === "'") return { type: 'string', value: this.quoted() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.c) && !',]};'.includes(this.c)) this.i++
    const t = this.s.slice(st, this.i)
    if (t === 'true') return { type: 'boolean', value: true }
    if (t === 'false') return { type: 'boolean', value: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(t)) return { type: 'integer', value: Number(t.replace(/_/g, '')) }
    const f = new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`)
    if (f.test(t)) return { type: 'float', value: Number(t.replace(/_/g, '')) }
    fail(`invalid value ${t}`)
  }

  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') {
        this.i++
        return items
      }
      items.push(this.value(prefix))
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') this.i++
      else if (this.c !== ']') fail('unterminated array')
    }
  }

  inline(prefix) {
    this.i++
    const t = new Table()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value([...prefix, ...names])
      assign(t, names, v, prefix)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === ',') this.i++
      else if (this.c === '}') {
        this.i++
        return t
      } else fail('unterminated inline table')
    }
  }
}

/** Walk names from table, creating tables; returns the table reached. */
function walk(table, names, prefix) {
  let t = table
  for (let k = 0; k < names.length; k++) {
    let n = t.map.get(names[k])
    if (n === undefined) {
      n = new Table()
      t.map.set(names[k], n)
    }
    if (n instanceof AotArray) n = n.items[n.items.length - 1]
    if (!(n instanceof Table)) fail(`${[...prefix, ...names.slice(0, k + 1)].join('.')} is not a table`)
    t = n
  }
  return t
}

function assign(table, names, value, prefix) {
  const t = walk(table, names.slice(0, -1), prefix)
  const last = names[names.length - 1]
  if (t.map.has(last)) fail(`key ${[...prefix, ...names].join('.')} is defined twice`)
  t.map.set(last, value)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let current = root
  let curPath = []
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const line = lines[ln]
      const p = new LineParser(line)
      p.ws()
      if (p.i >= line.length || p.c === '#' || p.c === ';') continue
      if (p.c === '[') {
        const aot = line[p.i + 1] === '['
        p.i += aot ? 2 : 1
        const names = p.dotted()
        p.ws()
        if (p.atEnd()) fail('unterminated table header')
        if (p.c !== ']') fail('unterminated table header')
        p.i++
        if (aot) {
          if (p.c !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, names.slice(0, -1), [])
        const last = names[names.length - 1]
        const path = names.join('.')
        const ex = parent.map.get(last)
        if (aot) {
          if (ex === undefined) {
            const a = new AotArray()
            parent.map.set(last, a)
            current = new Table()
            a.items.push(current)
          } else if (ex instanceof AotArray) {
            current = new Table()
            ex.items.push(current)
          } else fail(`${path} is not an array of tables`)
        } else if (ex === undefined) {
          current = new Table()
          current.header = true
          parent.map.set(last, current)
        } else if (ex instanceof Table) {
          if (ex.header) fail(`table ${path} is defined twice`)
          ex.header = true
          current = ex
        } else fail(`${path} is not a table`)
        curPath = names
      } else {
        const names = p.dotted()
        p.ws()
        if (p.c !== '=') fail('expected key = value')
        p.i++
        p.ws()
        const v = p.value([...curPath, ...names])
        p.ws()
        if (!p.atEnd()) fail('trailing text after a value')
        assign(current, names, v, curPath)
      }
    } catch (e) {
      if (e instanceof Fail) throw new ParseError(e.message, ln + 1)
      throw e
    }
  }
  return root
}
"}

