  if (mode === 'values') out += `${nameOf(k)}=${show(cellValue(k))}\n`
  else {
    const set = new Set()
    const f = cells.get(k)[0] === '=' ? getParsed(k) : null
    if (f) collectDeps(f.ast, set)
    out += `${nameOf(k)}:` + [...set].sort((a, b) => a - b).map((x) => ' ' + nameOf(x)).join('') + '\n'
  }
}
