      } else if (ex.t === 'array' && ex.aot) {
        const t = newTable(); ex.items.push(t); state.cur = t
      } else fail(`${path.join('.')} is not an array of tables`)
    } else if (!ex) {
      const t = newTable(); t.header = true
      parent.map.set(k, t); state.cur = t
    } else if (ex.t !== 'table') {
      fail(`${path.join('.')} is not a table`)
    } else {
      if (ex.header) fail(`table ${path.join('.')} is defined twice`)
      ex.header = true; state.cur = ex
    }
    state.path = path
    return
  }
  const parts = parseDotted()
  skipWs()
  if (peek() !== '=') fail('expected key = value')
  p++
  const v = parseValue(state.path)
  skipWs()
  if (!atEnd()) fail('trailing text after a value')
  assign(state.cur, state.path, parts, v)
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0)), y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = [...n.map.keys()].sort(cmp)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((i) => pad + toJson(i, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v)
}

function toKeys(n, path, out) {
  const kids = n.t === 'table'
    ? [...n.map.keys()].sort(cmp).map((k) => [path === null ? k : path + '.' + k, n.map.get(k)])
    : n.t === 'array' ? n.items.map((it, i) => [path + `[${i}]`, it]) : []
  for (const [p, c] of kids) { out.push(`${p} ${c.t}`); toKeys(c, p, out) }
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const state = { root: newTable(), cur: null, path: [] }
state.cur = state.root
for (let i = 0; i < lines.length; i++) {
  try { parseLine(lines[i], state) } catch (e) {
    if (!(e instanceof ConfigError)) throw e
    process.stderr.write(`error: line ${i + 1}: ${e.message}\n`)
    process.exit(2)
  }
}
if (mode === 'json') process.stdout.write(toJson(state.root, 0) + '\n')
else {
  const out = []
  toKeys(state.root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
