  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const mode = process.argv.slice(2)
  if (mode.length !== 1 || !['merge', 'merge2', 'regions'].includes(mode[0]))
    fail('error: usage: cli.js merge|merge2|regions')
  const lines = fs.readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) l === '%%%' ? docs.push([]) : docs[docs.length - 1].push(l)
  if (docs.length !== 3) fail('error: expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [...changes(base, mine, 'm'), ...changes(base, theirs, 't')]
  all.sort((a, b) => a.bs - b.bs) // stable: mine first on ties
  const out = []
  let conflict = false
  const regions = mode[0] === 'regions'
  const stable = (n) => { if (n > 0 && regions) out.push(`stable ${n}`) }
  let pos = 0, k = 0
  while (k < all.length) {
    const start = all[k].bs
    let end = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) {
      if (regions) stable(start - pos)
      else out.push(...base.slice(pos, start))
    }
    pos = end
    let res, label
    if (group.length === 1) {
      const c = group[0]
      res = (c.who === 'm' ? mine : theirs).slice(c.ss, c.se)
      label = c.who === 'm' ? 'mine' : 'theirs'
    } else {
      const baseL = base.slice(start, end)
      const pick = (who, doc) => {
        const g = group.filter(c => c.who === who)
        if (!g.length) return baseL
        const f = g[0], l = g[g.length - 1]
        return doc.slice(f.ss - (f.bs - start), l.se + (end - l.be))
      }
      const a = pick('m', mine), b = pick('t', theirs)
      if (eq(a, b)) { res = a; label = 'both' }
      else if (eq(a, baseL)) { res = b; label = 'theirs' }
      else if (eq(b, baseL)) { res = a; label = 'mine' }
      else {
        conflict = true
        if (regions) out.push(`conflict mine=${a.length} base=${baseL.length} theirs=${b.length}`)
        else {
          out.push('<<<<<<< mine', ...a)
          if (mode[0] === 'merge') out.push('||||||| base', ...baseL)
          out.push('=======', ...b, '>>>>>>> theirs')
