    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) {
      if (regions) stable(start - pos)
      else out.push(...base.slice(pos, start))
    }
    pos = end
    let res, label
    if (group.length === 1) {
      const c = group[0]
      res = (c.who === 'm' ? mine : theirs).slice(c.ss, c.se)
      label = c.who === 'm' ? 'mine' : 'theirs'
    } else {
      const baseL = base.slice(start, end)
      const pick = (who, doc) => {
        const g = group.filter(c => c.who === who)
        if (!g.length) return baseL
        const f = g[0], l = g[g.length - 1]
        return doc.slice(f.ss - (f.bs - start), l.se + (end - l.be))
      }
      const a = pick('m', mine), b = pick('t', theirs)
      if (eq(a, b)) { res = a; label = 'both' }
      else if (eq(a, baseL)) { res = b; label = 'theirs' }
      else if (eq(b, baseL)) { res = a; label = 'mine' }
      else {
        conflict = true
        if (regions) out.push(`conflict mine=${a.length} base=${baseL.length} theirs=${b.length}`)
        else {
          out.push('<<<<<<< mine', ...a)
          if (mode[0] === 'merge') out.push('||||||| base', ...baseL)
          out.push('=======', ...b, '>>>>>>> theirs')
        }
        continue
      }
    }
    if (regions) out.push(`${label} ${res.length}`)
    else out.push(...res)
  }
  if (regions) stable(base.length - pos)
  else out.push(...base.slice(pos))
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exit(conflict ? 1 : 0)
}
