import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'replay' && mode[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function int(field, s, least) {
  if (!UINT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  let n = 0
  try {
    for (const raw of lines) {
      n++
      const line = raw.trim()
      if (line === '' || line[0] === '#') continue
      const f = line.split(/\s+/)
      const d = f[0]
      const decl = () => { if (events.length) throw new Fail('declarations must come before the first event') }
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        decl()
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = int('capacity', f[2], 1)
        const refill = int('refill', f[3], 0)
        const per = int('per', f[4], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'b', capacity, refill, per, st: new Map() })
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        decl()
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = int('limit', f[2], 0)
        const span = int('span', f[3], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'w', limit, span, st: new Map() })
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        decl()
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const ps = f.slice(2).map(p => {
          if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          return policies.get(p)
        })
        routes.set(f[1], ps)
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', f[1], 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: f[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    }
  } catch (e) {
    if (e instanceof Fail) {
      process.stderr.write(`error: line ${n}: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }
  return { routes, events }
}

function advance(p, key, tick) {
  let s = p.st.get(key)
  if (p.kind === 'b') {
    const cap = p.capacity * p.per
    if (!s) { s = { v: cap, last: tick }; p.st.set(key, s) }
    else {
      s.v += p.refill * (tick - s.last)
      if (s.v > cap) s.v = cap
      s.last = tick
    }
  } else {
    if (!s) { s = { ticks: [] }; p.st.set(key, s) }
    const cut = tick - p.span
    s.ticks = s.ticks.filter(t => t > cut)
  }
