  let best = null
  for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
  let denied = null
  if (best !== null) {
    const ps = routes.get(best)
    const sts = ps.map(p => advance(p, key, tick))
    for (let i = 0; i < ps.length; i++) if (!allows(ps[i], sts[i])) { denied = ps[i]; break }
    if (!denied) ps.forEach((p, i) => record(p, sts[i], tick))
  }
  const c = counts.get(key) || { a: 0, d: 0 }
  counts.set(key, c)
  if (denied) { c.d++; td++ } else { c.a++; ta++ }
  out.push(denied ? `${tick} ${key} deny ${denied.name}` : `${tick} ${key} allow`)
}
