  process.stdout.write(out.map(l => l + '\n').join(''))
} else {
  const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let s = ''
  for (const k of keys) s += `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`
  s += `total allowed=${ta} denied=${td}\n`
  process.stdout.write(s)
}
