        const s = stateOf(p, key, tick)
        if (p.kind === 'bucket') {
          const cap = p.capacity * p.per
          s.units += p.refill * (tick - s.last)
          if (s.units > cap) s.units = cap
          s.last = tick
        } else {
          const cut = tick - p.span
          s.ticks = s.ticks.filter((t) => t > cut)
        }
        return s
      })
      for (let i = 0; i < ps.length && !denier; i++) {
        const p = ps[i]
        const ok = p.kind === 'bucket' ? sts[i].units >= p.per : BigInt(sts[i].ticks.length) < p.limit
        if (!ok) denier = p.name
      }
      if (!denier) {
        ps.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].units -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    const c = per.get(key) || { a: 0, d: 0 }
    per.set(key, c)
    if (denier) { c.d++; td++ } else { c.a++; ta++ }
    out.push(denier ? `${tick} ${key} deny ${denier}` : `${tick} ${key} allow`)
  }
  if (mode === 'summary') {
    out.length = 0
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out.push(`${k} allowed=${per.get(k).a} denied=${per.get(k).d}`)
    }
    out.push(`total allowed=${ta} denied=${td}`)
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
})
